node - <<'NODE'
const fs=require('fs'),crypto=require('crypto'),h=x=>crypto.createHash('sha256').update(x).digest('hex');const b=JSON.parse(fs.readFileSync('docs/remediation/design/W26.03/baseline.json')),w=JSON.parse(fs.readFileSync('docs/remediation/evidence/W26.03/worker.json')),a=JSON.parse(fs.readFileSync('docs/remediation/evidence/W26.03/artifact.json'));const clean=s=>s.replace(/\.$/,'');const prior=b.baseline_lint.results.flatMap(x=>x.messages.map(m=>[x.file,m.severity===1?'warning':'error',clean(m.message),m.ruleId].join('|'))).sort();let file='',current=[];for(const line of w.command_captures.static1.captures.map(c=>c.output).join('').split('\n')){if(line.startsWith('/'))file=line.slice(line.indexOf('/src/')+1);const m=line.match(/^\s+\d+:\d+\s+(warning|error)\s+(.+?)\s{2,}(\S+)\s*$/);if(m)current.push([file,m[1],clean(m[2]),m[3]].join('|'));}current.sort();const failures=a.files.filter(x=>h(fs.readFileSync(x.path))!==x.sha256);console.log(JSON.stringify({at:new Date().toISOString(),pins:a.files.length,failures,baseline:prior,current,identical:JSON.stringify(prior)===JSON.stringify(current),static_exit:w.command_captures.static1.exit_code,static_drained:w.command_captures.static1.drained,static_reruns:0},null,2));if(failures.length||JSON.stringify(prior)!==JSON.stringify(current)||current.length!==3)process.exit(1);
NODE
